var playlist = [

    {src: "data:audio/mpeg;base64,", title : "Good Girls", artist: "LANY"},
    {src: "data:audio/mpeg;base64,", title : "Pink Skies", artist: "LANY"},
    {src: "data:audio/mpeg;base64,", title : "you!", artist: "LANY"}
];


var currentTrack = 0;

var audio = new Audio(playlist[0]);
audio.volume = 0.5;


audio.addEventListener('ended', function() {

    currentTrack = (currentTrack + 1) % playlist.length;
    audio.src = playlist[currentTrack].src;
    audio.play();


    document.getElementById('.music-track').textContent = playlist[currentTrack].title;
    document.getElementById('.music-artist').textContent = playlist[currentTrack].artist;

});
